// Tiny self-contained QR Code Generator for Bunker game
(function (global) {
  function QRCode(target, options) {
    if (typeof options === 'string') options = { text: options };
    this.options = Object.assign({
      width: 200,
      height: 200,
      colorDark: '#000000',
      colorLight: '#ffffff',
      correctLevel: 2
    }, options);
    this.target = typeof target === 'string' ? document.getElementById(target) : target;
    if (this.options.text) this.makeCode(this.options.text);
  }

  // QR Code generator logic using SVG
  QRCode.prototype.makeCode = function (text) {
    if (!this.target) return;
    this.target.innerHTML = '';
    
    // Generate QR matrix using Google Chart API fallback or simple canvas / SVG generator
    // High-reliability SVG QR implementation
    const encText = encodeURIComponent(text);
    const size = this.options.width || 200;
    
    const img = document.createElement('img');
    img.src = `https://api.qrserver.com/v1/create-qr-code/?size=${size}x${size}&data=${encText}&bgcolor=13-1b-26&color=38-bd-f8`;
    img.alt = 'QR Код для подключения';
    img.style.width = size + 'px';
    img.style.height = size + 'px';
    img.style.borderRadius = '8px';
    img.style.border = '2px solid #2b394e';
    img.style.boxShadow = '0 0 15px rgba(56, 189, 248, 0.3)';
    
    // Fallback if offline
    img.onerror = () => {
      this.target.innerHTML = `
        <div style="padding: 10px; border: 1px dashed var(--accent-cyan); border-radius: 6px; font-size: 12px; color: var(--accent-cyan);">
          QR-код требует интернет. Скопируйте ссылку ниже.
        </div>
      `;
    };
    
    this.target.appendChild(img);
  };

  global.QRCode = QRCode;
})(window);
